    pos = sandbox.get_vehicle_position()
    x, y = pos
    vel = sandbox.get_vehicle_velocity()
    vx, vy = vel
    speed = math.hypot(vx, vy)

    # Apply force to counteract resistance in mud zone
    if 5.5 <= x <= 7.5:
        sandbox.apply_force(agent_body, (500.0, 0.0))
    # Apply force to counteract resistance in decel zone
    elif 9.5 <= x <= 11.0:
        sandbox.apply_force(agent_body, (500.0, 0.0))

    # Ensure speed trap requirement is met
    if x >= 9.0 and speed < 2.8:
        sandbox.apply_force(agent_body, (500.0, 0.0))

    # Adjust speed for checkpoint requirement
    if x >= 11.0:
        if speed < 1.1 or speed > 2.7:
            if speed < 1.1:
                sandbox.apply_force(agent_body, (500.0, 0.0))
            elif speed > 2.7:
                sandbox.apply_force(agent_body, (-500.0, 0.0))

    # Gate timing synchronization
    gates = [
        {'x': 10.0, 'initial_angle': 0.38, 'angular_velocity': 1.8, 'open_window_low': -0.18, 'open_window_high': 0.94},
